import { CAMPAIGN_ERRORS, type Campaign, type CampaignInput, type CampaignsApi, type CampaignStats } from '../campaigns';
import type { EventsApi } from '../events';
import { mockDelay, mockError, mockId } from './util';

/**
 * In-browser stand-in for the campaign endpoints. The real QR image is generated by the
 * server (SRS 4.14); the mock draws a placeholder that is clearly marked as not scannable.
 */

interface Stored extends Omit<Campaign, 'status' | 'link' | 'qrImageUrl' | 'qrDownloadUrl'> {
  token: string;
}

const ZERO: CampaignStats = { redemptions: 0, orders: 0, ticketsSold: 0, grossRevenue: 0, discountTotal: 0, netRevenue: 0 };

type Seed = Omit<Stored, 'id' | 'eventId' | 'validFrom' | 'validUntil' | 'createdAt' | 'token'>;

/** Prototype checkout shows STUDENT20 for "Almaty Nights". */
const SEED: Record<string, Seed[]> = {
  'evt-almaty-nights': [
    {
      name: 'University posters',
      code: 'STUDENT20',
      discountType: 'percent',
      discountValue: 20,
      maxRedemptions: 100,
      ticketTypeIds: [],
      enabled: true,
      stats: { redemptions: 38, orders: 31, ticketsSold: 38, grossRevenue: 247000, discountTotal: 49400, netRevenue: 197600 },
    },
  ],
};

function statusOf(c: Omit<Stored, 'token'>, now: Date): Campaign['status'] {
  if (!c.enabled) return 'disabled';
  if (c.maxRedemptions !== null && c.stats.redemptions >= c.maxRedemptions) return 'exhausted';
  if (now < c.validFrom) return 'scheduled';
  if (now > c.validUntil) return 'expired';
  return 'active';
}

/** A QR-looking SVG derived from the token. NOT a real QR code: it can't be scanned. */
export function mockQrSvg(token: string): string {
  const n = 25;
  let seed = [...token].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) >>> 0, 7);
  const rand = () => ((seed = (seed * 1103515245 + 12345) >>> 0) >>> 16) & 1;
  const finder = (x: number, y: number) =>
    `<rect x="${x}" y="${y}" width="7" height="7"/><rect x="${x + 1}" y="${y + 1}" width="5" height="5" fill="#fff"/><rect x="${x + 2}" y="${y + 2}" width="3" height="3"/>`;
  const inFinder = (x: number, y: number) => (x < 8 && y < 8) || (x >= n - 8 && y < 8) || (x < 8 && y >= n - 8);
  let cells = '';
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++) if (!inFinder(x, y) && rand()) cells += `<rect x="${x}" y="${y}" width="1" height="1"/>`;
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-2 -2 ${n + 4} ${n + 8}" shape-rendering="crispEdges">` +
    `<rect x="-2" y="-2" width="${n + 4}" height="${n + 8}" fill="#fff"/>` +
    `<g fill="#1b1b1b">${finder(0, 0)}${finder(n - 7, 0)}${finder(0, n - 7)}${cells}</g>` +
    `<text x="${n / 2}" y="${n + 4}" font-size="2.2" text-anchor="middle" font-family="sans-serif" fill="#b3402f">MOCK QR · NOT SCANNABLE</text>` +
    `</svg>`;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
}

const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const randomCode = () => Array.from({ length: 8 }, () => ALPHABET[Math.floor(Math.random() * ALPHABET.length)]).join('');
const randomToken = () => Array.from({ length: 16 }, () => Math.floor(Math.random() * 36).toString(36)).join('');

export interface MockCampaignsApi extends CampaignsApi {
  /** Mock-only: what the server records when a paid order used a campaign's code (SRS 4.14). */
  recordRedemption(eventId: string, code: string, order: { tickets: number; gross: number; discount: number }): Promise<void>;
}

export function createMockCampaignsApi(events: EventsApi, seed = SEED, now = () => new Date()): MockCampaignsApi {
  const store = new Map<string, Stored[]>();

  async function campaignsOf(eventId: string): Promise<Stored[]> {
    const event = await events.getEvent(eventId); // 404s like the real API
    if (!store.has(eventId)) {
      store.set(
        eventId,
        (seed[eventId] ?? []).map((s) => ({
          ...s,
          id: mockId('cmp'),
          eventId,
          token: randomToken(),
          validFrom: event.registrationOpensAt,
          validUntil: event.registrationClosesAt,
          createdAt: event.registrationOpensAt,
        })),
      );
    }
    return store.get(eventId)!;
  }

  const allCodes = () => [...store.values()].flat().map((c) => c.code);

  function present({ token, ...c }: Stored): Campaign {
    const link = `${window.location.origin}/events/${encodeURIComponent(c.eventId)}?campaign=${token}`;
    const qr = mockQrSvg(token);
    return structuredClone({ ...c, status: statusOf(c, now()), link, qrImageUrl: qr, qrDownloadUrl: qr });
  }

  return {
    async listCampaigns(eventId) {
      await mockDelay();
      return (await campaignsOf(eventId)).map(present);
    },
    async createCampaign(eventId, input: CampaignInput) {
      await mockDelay();
      const list = await campaignsOf(eventId);
      const code = input.code.trim().toUpperCase();
      if (code && allCodes().includes(code)) {
        throw mockError(409, CAMPAIGN_ERRORS.codeTaken, `The code ${code} is already in use. Choose another.`);
      }
      let generated = code;
      while (!generated || (!code && allCodes().includes(generated))) generated = randomCode();
      const created: Stored = {
        ...input,
        code: generated,
        id: mockId('cmp'),
        eventId,
        token: randomToken(),
        enabled: true,
        stats: { ...ZERO },
        createdAt: now(),
      };
      list.unshift(created);
      return present(created);
    },
    async recordRedemption(eventId, code, { tickets, gross, discount }) {
      const found = (await campaignsOf(eventId)).find((c) => c.code === code);
      if (!found) return;
      const s = found.stats;
      Object.assign(s, {
        redemptions: s.redemptions + 1,
        orders: s.orders + 1,
        ticketsSold: s.ticketsSold + tickets,
        grossRevenue: s.grossRevenue + gross,
        discountTotal: s.discountTotal + discount,
        netRevenue: s.netRevenue + gross - discount,
      });
    },
    async setCampaignEnabled(eventId, id, enabled) {
      await mockDelay();
      const found = (await campaignsOf(eventId)).find((c) => c.id === id);
      if (!found) throw mockError(404, 'campaign_not_found', 'Campaign not found.');
      found.enabled = enabled;
      return present(found);
    },
  };
}
